import * as React from "react";

const RAMP = "@#S%?*+;:,. ";
export function ASCIIRenderText({ text = "ASCII", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [t, setT] = React.useState(0);
  React.useEffect(() => { const id = setInterval(() => setT(p => p + 0.05), 100); return () => clearInterval(id); }, []);
  const cols = 40, rows = 12;
  const grid = Array.from({ length: rows }, (_, r) =>
    Array.from({ length: cols }, (_, c) => {
      const v = Math.sin(c / 4 + t) * Math.cos(r / 3 + t * 0.7) * 0.5 + 0.5;
      return RAMP[Math.floor(v * (RAMP.length - 1))];
    }).join("")
  ).join("
");
  return (
    <pre className={`font-mono text-[9px] leading-[1.3] text-green-400 select-none whitespace-pre ${className}`}>{grid}</pre>
  );
}

import * as React from "react";
import { ASCIIRenderText } from "./ascii-render-text";

export default function ASCIIRenderTextDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <ASCIIRenderText
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
